const sessionUser=JSON.parse(sessionStorage.getItem('shotcraftUser')||'{}');
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
async function signOut(){try{await fetch('/api/auth/logout',{method:'POST'})}finally{sessionStorage.removeItem('shotcraftUser');location.replace('/auth?mode=login')}}
document.body.classList.add('photographer-app');
const app=document.getElementById('app');
function openPhotographerMoodboardLightbox(image){
  document.querySelector('.moodboard-lightbox')?.remove();
  const modal=document.createElement('div');
  modal.className='moodboard-lightbox';
  modal.setAttribute('role','dialog');
  modal.setAttribute('aria-modal','true');
  modal.setAttribute('aria-label',image.alt||'Moodboard image preview');
  modal.innerHTML=`<div class="moodboard-lightbox-panel"><button type="button" class="moodboard-lightbox-close" aria-label="Close image preview">×</button><img src="${esc(image.currentSrc||image.src)}" alt="${esc(image.alt||'Moodboard image preview')}"></div>`;
  const close=()=>{modal.remove();document.body.classList.remove('moodboard-lightbox-open');document.removeEventListener('keydown',onKey)};
  const onKey=event=>{if(event.key==='Escape')close()};
  modal.addEventListener('click',event=>{if(event.target===modal||event.target.closest('.moodboard-lightbox-close'))close()});
  document.body.appendChild(modal);
  document.body.classList.add('moodboard-lightbox-open');
  document.addEventListener('keydown',onKey);
  modal.querySelector('.moodboard-lightbox-close').focus();
}
document.addEventListener('click',event=>{const image=event.target.closest('.moodboard .tiles img');if(!image)return;event.preventDefault();openPhotographerMoodboardLightbox(image)});
let timelineRequest=0;
const timelineMarkup=items=>`<section class="shared-timeline"><div class="eyebrow">Shoot journey</div><div class="timeline-track">${(items||[]).map(item=>`<div class="timeline-item ${item.completed?'complete':''}"><span class="timeline-dot">${item.completed?'✓':''}</span><div><b>${esc(item.label)}</b><small>${item.timestamp?esc(item.timestamp):'Upcoming'}</small></div></div>`).join('')}</div></section>`;
async function refreshTimeline(){const id=app.dataset.timelineId;if(!id||new URLSearchParams(location.search).get('view')==='production')return;const request=++timelineRequest;try{const response=await fetch(`/api/inquiries/${id}/timeline`,{cache:'no-store'}),data=await response.json();if(request!==timelineRequest)return;const existing=document.querySelector('.shared-timeline');if(existing)existing.outerHTML=timelineMarkup(data.timeline);else {const legacy=document.querySelector('.progress');if(legacy)legacy.outerHTML=timelineMarkup(data.timeline);else app.insertAdjacentHTML('beforeend',timelineMarkup(data.timeline))}}catch(_){} }
const briefCache=new Map();
