const photographerProjectWithScheduling=project;project=async id=>{await photographerProjectWithScheduling(id);const record=await getRecord(id);if(record.status!=='CLIENT_CONFIRMED')return;const requestResponse=await fetch(`/api/inquiries/${id}/schedule-recommendations`,{cache:'no-store'}),request=requestResponse.ok?await requestResponse.json():null;if(request?.status!=='PENDING_PHOTOGRAPHER')return;const target=app.querySelector('.detail-grid .next,.next');if(target&&!target.querySelector('[data-confirm-request]'))target.insertAdjacentHTML('beforeend',`<div class="actions"><button class="primary" data-confirm-request="${id}" data-time="${esc(request.selected_starts_at)}" data-location="${esc(request.selected_location)}">Confirm client’s time →</button></div>`)};
