async function showChangeReview(id){const record=await getRecord(id),p=payload(record),response=await fetch(`/api/inquiries/${id}/change-request`,{cache:'no-store'}),request=response.ok?await response.json():null;if(!request)return go('project',id);const assessment=request.assessment||{},updates=assessment.proposed_updates||{},isLocationChange=(assessment.impacts||[]).some(item=>item.toLowerCase().includes('location')),draft=isLocationChange?`Hi ${p.client_name||'there'}, thanks for letting me know. We can explore a different location for your shoot. Please share the new location you have in mind, or I can suggest a few suitable alternatives. Once we confirm the venue, I’ll update the meeting point and shoot plan.`:`Hi ${p.client_name||'there'}, I’ve reviewed your request and updated the shoot plan where needed. Please review the latest plan in ShotCraft, and let me know if you have any questions.`;current={view:'change-review',id:Number(id)};history.pushState(current,'',`/photographer?view=change-review&id=${id}`);setNav('projects');app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">AI change review</div><h1>Review the impact.</h1><p class="lede">The client’s request is preserved below. Apply the proposed plan changes only if they work for the shoot.</p></div><section class="card change-review"><div class="change-request"><div class="eyebrow">Client request</div><p>${esc(request.source_message)}</p></div><div class="change-impact"><div><div class="eyebrow">What changes</div><h2>${esc(assessment.request_summary||'Production plan update')}</h2><ul>${(assessment.impacts||[]).map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div><div><div class="eyebrow">Agent proposals</div>${Object.entries(updates).map(([section,items])=>`<article><b>${esc(section.replaceAll('_',' '))}</b><ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></article>`).join('')||'<p class="muted">Review the client request and update the plan manually if needed.</p>'}</div></div><form id="changeApprovalForm"><label for="changeClientMessage">Client update to send</label><textarea id="changeClientMessage" required maxlength="1200">${esc(draft)}</textarea><div class="actions"><button class="primary">Approve changes & send update →</button><button type="button" class="secondary" data-message-client="${id}">Open conversation</button><span class="muted" id="changeApprovalStatus"></span></div></form></section>`;bind();document.getElementById('changeApprovalForm').onsubmit=event=>approveChangeRequest(event,id)}

const changeReviewWithAIDraft=showChangeReview;showChangeReview=async id=>{await changeReviewWithAIDraft(id);const textarea=document.getElementById('changeClientMessage'),button=document.querySelector('#changeApprovalForm .primary'),status=document.getElementById('changeApprovalStatus');if(!textarea||!button)return;textarea.value='';textarea.placeholder='ShotCraft is drafting a response…';button.disabled=true;status.textContent='Drafting a client response…';try{const response=await fetch(`/api/inquiries/${id}/change-request/client-update-draft`,{method:'POST'}),raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{}if(!response.ok)throw Error(data.detail||'Could not draft a client response.');textarea.value=data.message||'';if(!textarea.value)throw Error('The agent returned an empty draft.')}catch(error){textarea.placeholder='Write a response to the client…';status.textContent=error.message}finally{button.disabled=false}}
