/* A month view keeps past shoot-day context visible and makes future months
   useful without turning the calendar into a narrow rolling window. */
const todayForCalendar=new Date();
let calendarMonthCursor=new Date(todayForCalendar.getFullYear(),todayForCalendar.getMonth(),1);
function calendarDayKey(day){return `${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`}
function sameCalendarDay(left,right){return calendarDayKey(left)===calendarDayKey(right)}
function compareCalendarEntries(left,right){
  const leftTime=wallClockDate(left.starts_at).valueOf(),rightTime=wallClockDate(right.starts_at).valueOf();
  if(Number.isNaN(leftTime))return Number.isNaN(rightTime)?0:1;
  if(Number.isNaN(rightTime))return-1;
  return leftTime-rightTime;
}
