  const monthEvents=entries.filter(inMonth),pending=entries.filter(item=>item.kind==='requested').sort(compareCalendarEntries);
  app.innerHTML=`<div class="head"><div><div class="eyebrow">Shoot calendar</div><h1>Your studio, in rhythm.</h1><p class="lede">Review completed shoots, upcoming sessions, and client time preferences across any month.</p></div></div>${pending.length?`<section class="card scheduling-queue"><div><div class="eyebrow">Needs confirmation</div><h2>${pending.length} preferred time${pending.length===1?'':'s'} awaiting you</h2></div>${pending.map(item=>{const p=payload(records[item.inquiry_id]||{});return`<article><div><b>${esc(p.client_name||'Client')} · ${esc(photographerCalendarDate(item.starts_at))}</b><span>${esc(photographerCalendarTime(item.starts_at))} – ${esc(photographerCalendarTime(item.ends_at))} · ${esc(item.location||'Location to be confirmed')}</span></div><button class="primary" data-confirm-request="${item.inquiry_id}" data-time="${esc(item.starts_at)}" data-location="${esc(item.location||'Location to be confirmed')}">Review & confirm →</button></article>`}).join('')}</section>`:''}<section class="calendar-board calendar-month"><div class="calendar-board-head"><div class="calendar-month-nav"><button class="secondary calendar-month-button" data-calendar-month="-1" aria-label="Previous month">←</button><div><b>${esc(calendarMonthCursor.toLocaleDateString(undefined,{month:'long',year:'numeric'}))}</b><span>${monthEvents.filter(item=>item.kind==='scheduled').length} confirmed shoot${monthEvents.filter(item=>item.kind==='scheduled').length===1?'':'s'}</span></div><button class="secondary calendar-month-button" data-calendar-today>Today</button><button class="secondary calendar-month-button" data-calendar-month="1" aria-label="Next month">→</button></div></div><div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=>`<span>${day}</span>`).join('')}</div><div class="calendar-month-grid">${days.map(day=>{const key=calendarDayKey(day),events=entries.filter(item=>String(item.starts_at).slice(0,10)===key).sort(compareCalendarEntries),outside=day.getMonth()!==calendarMonthCursor.getMonth();return`<article class="calendar-day ${events.length?'has-event':''} ${outside?'outside-month':''} ${sameCalendarDay(day,todayForCalendar)?'today':''}"><div><b>${day.getDate()}</b></div>${events.map(item=>{const p=payload(records[item.inquiry_id]||{});return`<button class="calendar-event ${item.kind}" data-project="${item.inquiry_id}">${esc(photographerCalendarTime(item.starts_at))}<span>${esc(p.client_name||'Client')} · ${esc(item.kind==='scheduled'?'Confirmed':'Requested')}</span></button>`}).join('')}</article>`}).join('')}</div></section>`;
  bind();
  document.querySelectorAll('[data-calendar-month]').forEach(button=>button.onclick=()=>{calendarMonthCursor.setMonth(calendarMonthCursor.getMonth()+Number(button.dataset.calendarMonth));photographerMonthlyCalendar()});
