  const labels={ANALYZING:'Understanding inquiry',NEEDS_DETAILS:'Collecting details',CREATING_BRIEF:'Building creative brief',CREATING_MOODBOARD:'Creating moodboard',BUILDING_PLAN:'Building shoot plan',CHECKING_AVAILABILITY:'Checking availability',REVIEWING_TIME_CHANGE:'Reviewing new time preferences',PHOTOGRAPHER_REVIEW:'Photographer review',CLIENT_REVIEW:'Client review',CONFIRMED:'Shoot confirmed',CANCELLATION_REVIEW:'Reviewing cancellation request',CANCELLATION_CONTACTED:'Client contacted',CANCELLATION_CLIENT_REPLIED:'Client replied',CANCELLED:'Shoot cancelled',BOOKING_RETAINED:'Booking retained',INTERRUPTED:'Needs attention'};
