calendar=async()=>{await renderCalendarWithoutSubtitle();app.querySelector('.head .lede')?.remove()};
function enhancePhotographerProfileForm(){const form=document.getElementById('photographerProfileForm'),input=document.getElementById('profileImage'),bio=document.getElementById('profileBio');if(!form||!input||input.dataset.enhanced)return;input.dataset.enhanced='true';input.classList.add('profile-file-input');const upload=document.createElement('div');upload.className='profile-upload-row';upload.innerHTML=`<label class="profile-upload-button" for="profileImage">Choose photo <span aria-hidden="true">↗</span></label><span class="profile-upload-name">No image selected</span>`;input.after(upload);const name=upload.querySelector('.profile-upload-name');input.addEventListener('change',()=>{const file=input.files?.[0];name.textContent=file?file.name:'No image selected';name.classList.toggle('selected',Boolean(file))});if(bio){const field=bio.closest('.field');field?.classList.add('bio-field');const meta=document.createElement('div');meta.className='bio-meta';meta.innerHTML='<span>Share the work, style, or experience clients can expect.</span><span class="bio-count"></span>';bio.after(meta);const count=meta.querySelector('.bio-count'),update=()=>count.textContent=`${bio.value.length} / ${bio.maxLength}`;bio.addEventListener('input',update);update()}}
const renderPhotographerProfileWithModernControls=photographerProfile;
