function showProfileSavedToast(done){document.querySelector('.profile-save-toast')?.remove();const toast=document.createElement('div'),message=document.createElement('span');toast.className='profile-save-toast';toast.setAttribute('role','status');toast.innerHTML='<i>✓</i>';toast.appendChild(message);document.body.appendChild(toast);let remaining=3;const update=()=>message.textContent=`Profile saved successfully. Taking you to Overview in ${remaining}…`;update();const countdown=setInterval(()=>{remaining-=1;if(remaining>0)update()},1000);setTimeout(()=>{clearInterval(countdown);toast.remove();done()},3000)}
function updatePhotographerSidebarAvatar(image){if(!image)return;const avatar=document.querySelector('.identity .profile-orb');if(avatar)avatar.outerHTML=`<span class="profile-orb profile-orb-image"><img src="${esc(image)}" alt=""></span>`}
savePhotographerProfile=async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button'),status=document.getElementById('profileStatus');button.disabled=true;status.textContent='Saving…';try{const image=await readProfileImage(document.getElementById('profileImage').files[0]);const response=await fetch('/api/auth/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({city:document.getElementById('profileCity').value,bio:document.getElementById('profileBio').value,specialties:document.getElementById('profileSpecialties').value,profile_image:image||sessionUser.profile_image||null})}),data=await response.json();if(!response.ok)throw Error(data.detail||'Could not save your profile.');Object.assign(sessionUser,data);sessionStorage.setItem('shotcraftUser',JSON.stringify(sessionUser));updatePhotographerSidebarAvatar(data.profile_image);showProfileSavedToast(()=>go('overview'))}catch(error){status.textContent=error.message;button.disabled=false}}

// Legacy requests and messages may still contain stored 24-hour preferences.
// Format them only at the display boundary; the underlying schedule data stays
// in its stable machine-readable form.
function formatScheduleTextForDisplay(value){
  return String(value||'')
    .replace(/Requested date:\s*(\d{4}-\d{2}-\d{2})/g,(_,date)=>`Requested date: ${formatDate(date)}`)
    .replace(/Your shoot is confirmed for\s+(\d{4}-\d{2}-\d{2})[ T](\d{1,2}:\d{2})(?=\s+at\b)/g,(_,date,time)=>`Your shoot is confirmed for ${formatDate(`${date}T${time}`)}`)
    .replace(/(\d{1,2}:\d{2})\s*[–-]\s*(\d{1,2}:\d{2})/g,(_,start,end)=>`${formatTimeOfDay(start)} – ${formatTimeOfDay(end)}`);
}
function formatVisibleScheduleText(){
  app.querySelectorAll('.message p,.change-request p,.schedule-compare div:nth-child(2) b').forEach(node=>{
    if(node.dataset.scheduleFormat)return;
    node.textContent=formatScheduleTextForDisplay(node.textContent);
    node.dataset.scheduleFormat='true';
  });
}
new MutationObserver(formatVisibleScheduleText).observe(app,{childList:true,subtree:true});

/* Confirmed schedule changes are reviewed here, then sent back as selectable options. */
function openCancellationReview(id){const record=inquiries.find(item=>item.id==id);if(!record)return;const p=payload(record),amount=Number(p.budget||0),fee=Number(record.cancellation_fee||0),refund=Number(record.cancellation_refund??Math.max(amount-fee,0)),modal=document.createElement('div');modal.className='cancel-modal';modal.innerHTML=`<section class="cancel-dialog"><button class="cancel-close" aria-label="Close">×</button><div class="eyebrow">Client cancellation request</div><h2>Decide what happens next.</h2><p><b>${esc(record.cancellation_reason||'Cancellation requested')}</b>${record.cancellation_note?`<br>${esc(record.cancellation_note)}`:''}</p><div class="cancellation-policy-review"><small>POLICY GUIDANCE</small><b>Booking $${amount.toFixed(2)} · Suggested fee $${fee.toFixed(2)} · Estimated refund $${refund.toFixed(2)}</b><span>48+ hours: no fee · 24–48 hours: 25% · Under 24 hours: 50%</span></div><fieldset class="cancellation-fee-options"><legend>If you approve</legend><label><input type="radio" name="fee_mode" value="POLICY" checked> Apply suggested policy fee</label><label><input type="radio" name="fee_mode" value="WAIVED"> Waive the fee</label><label><input type="radio" name="fee_mode" value="CUSTOM"> Custom fee <input type="number" name="custom_fee" min="0" max="${amount}" step="0.01" value="${fee.toFixed(2)}" hidden disabled></label></fieldset><label>Message to client<textarea name="message" maxlength="1200" placeholder="Required when declining; optional when approving…"></textarea></label><div class="cancel-review-actions"><button class="primary" data-cancel-decision="approve" data-id="${id}">Approve cancellation</button><button class="secondary" data-cancel-decision="keep" data-id="${id}">Decline and keep booking</button><button class="secondary" data-cancel-message="${id}">Message client first</button></div><span class="muted cancel-status"></span></section>`;modal.onclick=event=>{if(event.target===modal||event.target.closest('.cancel-close'))modal.remove()};document.body.append(modal)}
const openCancellationReviewWithFeePercentage=openCancellationReview;
openCancellationReview=id=>{
  openCancellationReviewWithFeePercentage(id);
  const record=inquiries.find(item=>item.id==id),amount=Number(payload(record||{}).budget||0),suggestedFee=Number(record?.cancellation_fee||0),suggestedPercent=amount?Math.round(suggestedFee/amount*100):0,modal=document.querySelector('.cancel-modal'),guidance=modal?.querySelector('.cancellation-policy-review b'),custom=modal?.querySelector('[name="custom_fee"]');
  if(!modal||!guidance)return;
  const update=()=>{
    const mode=modal.querySelector('[name="fee_mode"]:checked')?.value||'POLICY';
    const fee=mode==='WAIVED'?0:mode==='CUSTOM'?Math.min(Math.max(Number(custom?.value||0),0),amount):suggestedFee;
    const percent=amount?fee/amount*100:0,label=mode==='WAIVED'?'Fee waived':mode==='CUSTOM'?'Custom fee':`Policy fee ${suggestedPercent}%`;
    guidance.textContent=`Booking $${amount.toFixed(2)} · ${label}: ${percent.toFixed(percent%1?1:0)}% ($${fee.toFixed(2)}) · Estimated refund $${Math.max(amount-fee,0).toFixed(2)}`;
    if(custom){custom.hidden=mode!=='CUSTOM';custom.disabled=mode!=='CUSTOM'}
  };
  modal.querySelectorAll('[name="fee_mode"]').forEach(input=>input.addEventListener('change',update));
  custom?.addEventListener('input',update);
  update();
  const policy=modal.querySelector('.cancellation-policy-review');
  const agentPanel=document.createElement('section');
  agentPanel.className='cancellation-agent-review';
  agentPanel.setAttribute('aria-live','polite');
  policy.insertAdjacentElement('afterend',agentPanel);
  let attempts=0;
  const loadReview=async()=>{
    if(!modal.isConnected)return;
    try{
      const response=await fetch(`/api/inquiries/${id}/cancellation/agent-review`,{cache:'no-store'});
      if(!response.ok)throw Error('Review status is unavailable.');
      const data=await response.json(),review=data.review||{},decision=review.decision;
      if(data.status==='RUNNING'&&attempts++<30){
        agentPanel.innerHTML='<div class="cancellation-agent-heading"><span class="eyebrow">Strands cancellation review</span><b>Checking the booking and policy…</b></div><p>The shoot stays scheduled while the agent reviews the request. You can still decide at any time.</p>';
        setTimeout(loadReview,2000);
      }else if(data.status==='COMPLETE'&&decision){
        const action={APPROVE:'Consider approving',DECLINE:'Consider declining',MESSAGE_FIRST:'Consider messaging first'}[decision.recommended_action]||'Review the request';
        const activity=Array.isArray(review.activity)?review.activity:[];
        agentPanel.innerHTML=`<div class="cancellation-agent-heading"><span class="eyebrow">Strands cancellation review</span><b>${action}</b></div><p>${esc(decision.rationale||'')}</p><ul>${activity.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>${decision.message_draft?`<div class="cancellation-agent-draft"><span>Suggested message · editable before sending</span><p>${esc(decision.message_draft)}</p><button type="button" class="secondary" data-use-cancellation-draft>Use this draft</button></div>`:''}<small>The photographer makes the final decision. The policy fee shown above is calculated by ShotCraft.</small>`;
        agentPanel.querySelector('[data-use-cancellation-draft]')?.addEventListener('click',()=>{modal.querySelector('textarea[name="message"]').value=decision.message_draft;modal.querySelector('textarea[name="message"]').focus()});
      }else{
        agentPanel.innerHTML='<div class="cancellation-agent-heading"><span class="eyebrow">Strands cancellation review</span><b>Review unavailable</b></div><p>Use the booking, policy, and client reason above to make your decision. The shoot remains scheduled until you act.</p>';
      }
    }catch(error){agentPanel.innerHTML='<div class="cancellation-agent-heading"><span class="eyebrow">Strands cancellation review</span><b>Could not load the review</b></div><p>You can still review the policy and decide. Reopen this request to check for an updated recommendation.</p>'}
  };
  loadReview();
};
async function decideCancellation(button){const modal=button.closest('.cancel-modal'),status=modal.querySelector('.cancel-status'),message=modal.querySelector('textarea').value,feeMode=modal.querySelector('[name="fee_mode"]:checked')?.value||'POLICY',customFee=Number(modal.querySelector('[name="custom_fee"]')?.value||0);modal.querySelectorAll('button').forEach(item=>item.disabled=true);status.textContent='Saving decision…';try{const response=await fetch(`/api/inquiries/${button.dataset.id}/cancellation/${button.dataset.cancelDecision}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,fee_mode:feeMode,cancellation_fee:feeMode==='CUSTOM'?customFee:null})}),data=await response.json();if(!response.ok)throw Error(data.detail||'Could not save the cancellation decision.');modal.remove();await refresh();go('project',button.dataset.id)}catch(error){status.textContent=error.message;modal.querySelectorAll('button').forEach(item=>item.disabled=false)}}
document.addEventListener('click',event=>{const review=event.target.closest('[data-review-cancellation]'),decision=event.target.closest('[data-cancel-decision]'),message=event.target.closest('[data-cancel-message]');if(review){event.preventDefault();openCancellationReview(review.dataset.reviewCancellation)}else if(decision){event.preventDefault();decideCancellation(decision)}else if(message){event.preventDefault();message.closest('.cancel-modal')?.remove();go('messages',message.dataset.cancelMessage)}});
function toLocalDateTime(value){const date=new Date(value);if(Number.isNaN(date.valueOf()))return'';const pad=part=>String(part).padStart(2,'0');return`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`}
async function sendRescheduleOptions(event,id){event.preventDefault();const form=event.currentTarget,button=form.querySelector('.primary'),status=form.querySelector('.reschedule-status'),location=form.elements.location.value.trim(),suggestions=[...form.querySelectorAll('[data-reschedule-slot]')].map(row=>({starts_at:row.querySelector('[name="start"]').value,ends_at:row.querySelector('[name="end"]').value,location,rationale:'A revised time proposed by your photographer.'}));button.disabled=true;status.textContent='Sending revised options…';try{const response=await fetch(`/api/inquiries/${id}/schedule-proposals?photographer_email=${encodeURIComponent(sessionUser.email||'')}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({suggestions})}),data=await response.json();if(!response.ok)throw Error(data.detail||'Could not send the revised times.');await refresh();status.textContent='Options sent. The client can now choose a time.';setTimeout(()=>go('project',id),650)}catch(error){status.textContent=error.message;button.disabled=false}}
const changeReviewWithRescheduleOptions=showChangeReview;
showChangeReview=async id=>{
  await changeReviewWithRescheduleOptions(id);
  const response=await fetch(`/api/inquiries/${id}/change-request`,{cache:'no-store'}),request=response.ok?await response.json():null,change=request?.assessment?.schedule_change;
  if(!change||app.querySelector('.reschedule-review'))return;
  const record=await getRecord(id),p=payload(record),location=record.meeting_location||p.location||'',anchor=app.querySelector('.change-request');
  app.querySelector('.change-impact')?.remove();
  app.querySelector('#changeApprovalForm')?.remove();
  const decision=app.querySelector('.change-decision');
  if(decision)decision.innerHTML='<div><div class="eyebrow">Scheduling negotiation</div><b>The current booking remains protected.</b><p>Review the conflict-free alternatives below before anything is sent to the client.</p></div>';
  anchor?.insertAdjacentHTML('afterend',`<section class="reschedule-review reschedule-loading"><div class="eyebrow">AI schedule analysis</div><h2>Finding conflict-free options…</h2><p class="muted">Checking the requested duration, preferred windows, confirmed bookings, and a 30-minute buffer.</p></section>`);
  const panel=app.querySelector('.reschedule-review');
  try{
    const previewResponse=await fetch(`/api/inquiries/${id}/schedule-preview`,{cache:'no-store'}),preview=await previewResponse.json();
    if(!previewResponse.ok||!preview.suggestions?.length)throw Error(preview.detail||'No available options were found.');
    const slot=(suggestion,index)=>`<article class="reschedule-option" data-reschedule-slot><div class="reschedule-option-head"><span>${suggestion.outside_preferred_window?'Outside preferred window':index===0?'Best match':'Available alternative'}</span><small>${esc(suggestion.rationale||'Conflict-free option')}</small></div><div class="reschedule-slot"><label>Starts<input name="start" type="datetime-local" value="${esc(suggestion.starts_at)}" required></label><label>Ends<input name="end" type="datetime-local" value="${esc(suggestion.ends_at)}" required></label></div></article>`;
    const agentActivity=(preview.agent_activity||[]).filter(item=>!String(item).includes('unavailable')).map(item=>`<li>${esc(item)}</li>`).join('');
    panel.classList.remove('reschedule-loading');
    panel.innerHTML=`<div class="eyebrow">Strands time-change review</div><h2>Review conflict-free times</h2><p class="muted">${esc(preview.summary||`Every option matches the ${p.duration_minutes||120}-minute duration and includes a 30-minute buffer around confirmed shoots.`)}</p>${agentActivity?`<div class="agent-activity"><b>What ShotCraft checked</b><ul>${agentActivity}</ul><span>${preview.agent_used_tools?'Strands agent completed its tool-assisted review.':'Validated scheduling fallback completed.'}</span></div>`:''}<div class="schedule-compare"><div><small>Current booking stays active</small><b>${esc(record.call_time?formatDate(record.call_time):'Not yet scheduled')}</b></div><div><small>Client preference</small><b>${esc(formatDate(change.shoot_date))} · ${esc((change.availability_windows||[]).map(formatAvailabilityWindow).join(', '))}</b></div></div><form id="rescheduleOptionsForm">${preview.suggestions.map(slot).join('')}<div class="field"><label>Meeting location<input name="location" value="${esc(location)}" required></label></div><div class="actions"><button class="primary">Approve & send these options →</button><button class="secondary" type="button" data-message-client="${id}">Message client first</button><span class="muted reschedule-status"></span></div></form>`;
    document.getElementById('rescheduleOptionsForm').onsubmit=event=>sendRescheduleOptions(event,id);
  }catch(error){
    panel.classList.remove('reschedule-loading');
    panel.innerHTML=`<div class="eyebrow">No matching availability</div><h2>Ask for another date</h2><p class="muted">${esc(error.message)} The current booking remains unchanged.</p><button class="secondary" type="button" data-message-client="${id}">Message client →</button>`;
    bind();
  }
};
